import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] skill = new long[n];
        for (int i = 0; i < n; i++) skill[i] = nextLong();
        // best[b + n] = smallest skill prefix seen with count balance b.
        long[] best = new long[2 * n + 1];
        boolean[] has = new boolean[2 * n + 1];
        has[n] = true;
        long total = 0, answer = 0;
        int balance = 0;
        for (int i = 0; i < n; i++) {
            balance += nextInt() != 0 ? 1 : -1;
            total += skill[i];
            int b = balance + n;
            if (has[b]) {
                answer = Math.max(answer, total - best[b]);
                best[b] = Math.min(best[b], total);
            } else {
                has[b] = true;
                best[b] = total;
            }
        }
        System.out.println(answer);
    }
}

